def solve():
    n = int(input())
    s = input().strip()

    def is_valid(k):
        # Get all substrings of length k
        seen = {}
        for i in range(n - k + 1):
            substring = s[i:i+k]
            if substring in seen:
                return False
            seen[substring] = True
        return True

    # Binary search on the answer
    left, right = 1, n
    result = n

    while left <= right:
        mid = (left + right) // 2
        if is_valid(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    print(result)

